import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor weight,
                              c10::optional<torch::Tensor> bias,
                              int stride, int pad_h, int pad_w,
                              int dil_h, int dil_w);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv2d_kernel(
    const T* __restrict__ X,   // [N, Cin, H, Win]
    const T* __restrict__ Wt,  // [Cout, Cin, Kh, Kw]
    const T* __restrict__ Bs,  // [Cout] or nullptr
    T* __restrict__ Y,         // [N, Cout, Hout, Wout]
    int N, int Cin, int H, int Win,
    int Cout, int Kh, int Kw,
    int stride, int pad_h, int pad_w, int dil_h, int dil_w,
    int Hout, int Wout)
{
  constexpr int Threads    = 256;
  constexpr int PVec       = 4;
  constexpr int OcPerBlock = 4;

  const int tid = threadIdx.x;

  const int n       = blockIdx.z;
  const int oc_tile = blockIdx.y;
  const int oc_base = oc_tile * OcPerBlock;

  const int P_total = Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  // ---- CuTe global tensors ----
  int64_t sXn = (int64_t)Cin * H * Win;
  int64_t sXc = (int64_t)H * Win;

  int64_t sYn = (int64_t)Cout * Hout * Wout;
  int64_t sYc = (int64_t)Hout * Wout;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, H, Win),
      make_stride(sXc, (int64_t)Win, Int<1>{}));

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Hout, Wout),
      make_stride(sYc, (int64_t)Wout, Int<1>{}));

  auto mW = make_tensor(
      make_gmem_ptr(Wt),
      make_shape(Cout, Cin, Kh, Kw),
      make_stride((int64_t)Cin * Kh * Kw, (int64_t)Kh * Kw, (int64_t)Kw, Int<1>{}));

  // ---- Shared memory tile for weights of this Oc block ----
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);

  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<OcPerBlock>{}, Cin, Kh, Kw),
      make_stride((int64_t)Cin * Kh * Kw, (int64_t)Kh * Kw, (int64_t)Kw, Int<1>{}));

  int64_t wsize = (int64_t)OcPerBlock * Cin * Kh * Kw;
  for (int64_t idx = tid; idx < wsize; idx += Threads) {
    int64_t occ  = idx / ((int64_t)Cin * Kh * Kw);
    int64_t rem  = idx % ((int64_t)Cin * Kh * Kw);
    int64_t ci   = rem / ((int64_t)Kh * Kw);
    int64_t rem2 = rem % ((int64_t)Kh * Kw);
    int64_t kh   = rem2 / Kw;
    int64_t kw   = rem2 % Kw;

    int oc = oc_base + (int)occ;
    T val = T(0);
    if (oc < Cout) {
      val = mW(oc, (int)ci, (int)kh, (int)kw);
    }
    sW((int)occ, (int)ci, (int)kh, (int)kw) = val;
  }
  __syncthreads();

  // ---- Precompute output positions for this thread ----
  int p_idx[PVec];
  int oh_arr[PVec];
  int ow_arr[PVec];
  bool valid[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      oh_arr[i] = p / Wout;
      ow_arr[i] = p - oh_arr[i] * Wout;
      valid[i]  = true;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
      valid[i]  = false;
    }
  }

  // ---- Accumulators (init with bias) ----
  float acc[OcPerBlock][PVec];
  #pragma unroll
  for (int occ = 0; occ < OcPerBlock; ++occ) {
    int oc = oc_base + occ;
    float bval = 0.0f;
    if (Bs != nullptr && oc < Cout) {
      bval = (float)Bs[oc];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[occ][i] = bval;
    }
  }

  // ---- Main reduction loop over Cin, Kh, Kw ----
  for (int ci = 0; ci < Cin; ++ci) {
    for (int kh = 0; kh < Kh; ++kh) {
      int ih_arr[PVec];
      bool hvalid[PVec];

      #pragma unroll
      for (int i = 0; i < PVec; ++i) {
        if (!valid[i]) {
          ih_arr[i] = 0;
          hvalid[i] = false;
          continue;
        }
        int ih = oh_arr[i] * stride - pad_h + kh * dil_h;
        ih_arr[i] = ih;
        hvalid[i] = (ih >= 0 && ih < H);
      }

      for (int kw = 0; kw < Kw; ++kw) {
        float wv[OcPerBlock];
        #pragma unroll
        for (int occ = 0; occ < OcPerBlock; ++occ) {
          wv[occ] = (float)sW(occ, ci, kh, kw);
        }

        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
          if (!valid[i] || !hvalid[i]) continue;
          int iw = ow_arr[i] * stride - pad_w + kw * dil_w;
          if (iw < 0 || iw >= Win) continue;

          float xval = (float)mX(ci, ih_arr[i], iw);

          #pragma unroll
          for (int occ = 0; occ < OcPerBlock; ++occ) {
            acc[occ][i] += xval * wv[occ];
          }
        }
      }
    }
  }

  // ---- Store results ----
  #pragma unroll
  for (int occ = 0; occ < OcPerBlock; ++occ) {
    int oc = oc_base + occ;
    if (oc >= Cout) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (!valid[i]) continue;
      mY(oc, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[occ][i]);
    }
  }
}

torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor weight,
                              c10::optional<torch::Tensor> bias,
                              int stride, int pad_h, int pad_w,
                              int dil_h, int dil_w) {
  TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "x and weight must be CUDA tensors");
  if (bias.has_value()) TORCH_CHECK(bias.value().is_cuda(), "bias must be CUDA");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
  if (bias.has_value()) TORCH_CHECK(bias.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(weight.dim() == 4, "weight must be [Cout, Cin, Kh, Kw]");

  auto x_c = x.contiguous();
  auto w_c = weight.contiguous();

  int64_t N   = x_c.size(0);
  int64_t Cin = x_c.size(1);
  int64_t H   = x_c.size(2);
  int64_t Win = x_c.size(3);

  int64_t Cout = w_c.size(0);
  TORCH_CHECK(w_c.size(1) == Cin, "weight Cin mismatch");
  int64_t Kh = w_c.size(2);
  int64_t Kw = w_c.size(3);

  TORCH_CHECK(stride > 0 && dil_h > 0 && dil_w > 0, "stride and dilation must be > 0");
  TORCH_CHECK(pad_h >= 0 && pad_w >= 0, "padding must be >= 0");

  int64_t Hout = (H + 2 * pad_h - dil_h * (Kh - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * pad_w - dil_w * (Kw - 1) - 1) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (bias.has_value()) {
    b_c = bias.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

  constexpr int Threads    = 256;
  constexpr int PVec       = 4;
  constexpr int OcPerBlock = 4;

  int64_t P_total = Hout * Wout;
  int64_t PTile   = (int64_t)Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout + OcPerBlock - 1) / OcPerBlock),
      (unsigned)N
  );

  size_t smem_bytes = (size_t)OcPerBlock * (size_t)Cin * (size_t)Kh * (size_t)Kw * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv2d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)Kh, (int)Kw,
      stride, pad_h, pad_w, dil_h, dil_w,
      (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 2D convolution with square input, asymmetric kernel, dilation and
    padding, implemented with a single custom CUDA kernel using CuTe tensors
    for indexing and a shared-memory weight-tile cooperative-tiled schedule.
    """

    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: tuple,
                 stride: int = 1,
                 padding: tuple = (0, 0),
                 dilation: tuple = (1, 1),
                 bias: bool = False) -> None:
        super().__init__()

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = tuple(kernel_size)
        self.stride = int(stride)
        self.padding = tuple(padding)
        self.dilation = tuple(dilation)

        Cin = self.in_channels
        Cout = self.out_channels
        Kh, Kw = self.kernel_size

        self.weight = nn.Parameter(torch.empty(Cout, Cin, Kh, Kw))
        if bias:
            self.bias = nn.Parameter(torch.empty(Cout))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            Cin = self.in_channels
            Kh, Kw = self.kernel_size
            fan_in = Cin * Kh * Kw
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding[0]),
            int(self.padding[1]),
            int(self.dilation[0]),
            int(self.dilation[1]),
        )

