import math
import torch
import torch.nn as nn
import torch.nn.init as init

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64


PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.visible .entry conv2d_kernel(
    .param .u64 conv2d_kernel_param_0,
    .param .u64 conv2d_kernel_param_1,
    .param .u64 conv2d_kernel_param_2,
    .param .u64 conv2d_kernel_param_3,
    .param .u32 conv2d_kernel_param_4,
    .param .u32 conv2d_kernel_param_5,
    .param .u32 conv2d_kernel_param_6,
    .param .u32 conv2d_kernel_param_7,
    .param .u32 conv2d_kernel_param_8,
    .param .u32 conv2d_kernel_param_9,
    .param .u32 conv2d_kernel_param_10,
    .param .u32 conv2d_kernel_param_11,
    .param .u32 conv2d_kernel_param_12,
    .param .u32 conv2d_kernel_param_13,
    .param .u32 conv2d_kernel_param_14,
    .param .u32 conv2d_kernel_param_15,
    .param .u32 conv2d_kernel_param_16,
    .param .u32 conv2d_kernel_param_17
)
{
    .reg .pred %p<25>;
    .reg .f32  %f<10>;
    .reg .b32  %r<70>;
    .reg .b64  %rd<100>;

    // ---- load params ----
    ld.param.u64 %rd1, [conv2d_kernel_param_0];   // X ptr
    ld.param.u64 %rd2, [conv2d_kernel_param_1];   // W ptr
    ld.param.u64 %rd3, [conv2d_kernel_param_2];   // B ptr (0 == no bias)
    ld.param.u64 %rd4, [conv2d_kernel_param_3];   // Y ptr
    ld.param.u32 %r1,  [conv2d_kernel_param_4];   // N
    ld.param.u32 %r2,  [conv2d_kernel_param_5];   // Cin
    ld.param.u32 %r3,  [conv2d_kernel_param_6];   // H
    ld.param.u32 %r4,  [conv2d_kernel_param_7];   // Win
    ld.param.u32 %r5,  [conv2d_kernel_param_8];   // Cout
    ld.param.u32 %r6,  [conv2d_kernel_param_9];   // Kh
    ld.param.u32 %r7,  [conv2d_kernel_param_10];  // Kw
    ld.param.u32 %r8,  [conv2d_kernel_param_11];  // stride
    ld.param.u32 %r9,  [conv2d_kernel_param_12];  // pad_h
    ld.param.u32 %r10, [conv2d_kernel_param_13];  // pad_w
    ld.param.u32 %r11, [conv2d_kernel_param_14];  // dil_h
    ld.param.u32 %r12, [conv2d_kernel_param_15];  // dil_w
    ld.param.u32 %r13, [conv2d_kernel_param_16];  // Hout
    ld.param.u32 %r14, [conv2d_kernel_param_17];  // Wout

    cvta.to.global.u64 %rd10, %rd1;   // Xg
    cvta.to.global.u64 %rd11, %rd2;   // Wg
    cvta.to.global.u64 %rd12, %rd4;   // Yg

    // ---- global flattened output index ----
    mov.u32 %r20, %ctaid.x;
    mov.u32 %r21, %ntid.x;
    mov.u32 %r22, %tid.x;
    mad.lo.s32 %r23, %r20, %r21, %r22;   // idx

    // total = N*Cout*Hout*Wout  (64-bit compare to be safe)
    cvt.s64.s32 %rd20, %r1;
    cvt.s64.s32 %rd21, %r5;
    cvt.s64.s32 %rd22, %r13;
    cvt.s64.s32 %rd23, %r14;
    mul.lo.s64 %rd24, %rd20, %rd21;
    mul.lo.s64 %rd25, %rd24, %rd22;
    mul.lo.s64 %rd26, %rd25, %rd23;      // total

    cvt.s64.s32 %rd27, %r23;
    setp.ge.s64 %p1, %rd27, %rd26;
    @%p1 bra DONE;

    // decompose idx -> n, oc, oh, ow  (Y layout [N,Cout,Hout,Wout])
    div.s32 %r30, %r23, %r14;      // tmp  = idx / Wout
    rem.s32 %r31, %r23, %r14;      // ow   = idx % Wout
    div.s32 %r32, %r30, %r13;      // tmp2 = tmp / Hout
    rem.s32 %r33, %r30, %r13;      // oh   = tmp % Hout
    div.s32 %r34, %r32, %r5;       // n    = tmp2 / Cout
    rem.s32 %r35, %r32, %r5;       // oc   = tmp2 % Cout

    // ---- accumulator init (bias) ----
    mov.f32 %f1, 0f00000000;
    setp.eq.s64 %p2, %rd3, 0;
    @%p2 bra SKIP_BIAS;

