LOOP_CI:
    setp.ge.s32 %p3, %r40, %r2;
    @%p3 bra END_CI;

    mov.u32 %r41, 0;   // kh = 0

LOOP_KH:
    setp.ge.s32 %p4, %r41, %r6;
    @%p4 bra END_KH;

    // ih = oh*stride - pad_h + kh*dil_h
    mul.lo.s32 %r42, %r33, %r8;
    mul.lo.s32 %r43, %r41, %r11;
    add.s32 %r44, %r42, %r43;
    sub.s32 %r45, %r44, %r9;       // ih

    setp.lt.s32 %p5, %r45, 0;
    setp.ge.s32 %p6, %r45, %r3;
    or.pred %p7, %p5, %p6;
    @%p7 bra SKIP_KH;

    mov.u32 %r46, 0;   // kw = 0

LOOP_KW:
    setp.ge.s32 %p8, %r46, %r7;
    @%p8 bra END_KW;

    // iw = ow*stride - pad_w + kw*dil_w
    mul.lo.s32 %r47, %r31, %r8;
    mul.lo.s32 %r48, %r46, %r12;
    add.s32 %r49, %r47, %r48;
    sub.s32 %r50, %r49, %r10;      // iw

    setp.lt.s32 %p9,  %r50, 0;
    setp.ge.s32 %p10, %r50, %r4;
    or.pred %p11, %p9, %p10;
    @%p11 bra SKIP_KW;

    // X index = ((n*Cin + ci)*H + ih)*Win + iw
    cvt.s64.s32 %rd40, %r34;
    cvt.s64.s32 %rd41, %r2;
    cvt.s64.s32 %rd42, %r40;
    cvt.s64.s32 %rd43, %r3;
    cvt.s64.s32 %rd44, %r45;
    cvt.s64.s32 %rd45, %r4;
    cvt.s64.s32 %rd46, %r50;

    mul.lo.s64 %rd47, %rd40, %rd41;
    add.s64 %rd48, %rd47, %rd42;
    mul.lo.s64 %rd49, %rd48, %rd43;
    add.s64 %rd50, %rd49, %rd44;
    mul.lo.s64 %rd51, %rd50, %rd45;
    add.s64 %rd52, %rd51, %rd46;
    shl.b64 %rd53, %rd52, 2;
    add.s64 %rd54, %rd10, %rd53;
    ld.global.nc.f32 %f2, [%rd54];

    // W index = ((oc*Cin + ci)*Kh + kh)*Kw + kw
    cvt.s64.s32 %rd55, %r35;
    cvt.s64.s32 %rd56, %r6;
    cvt.s64.s32 %rd57, %r41;
    cvt.s64.s32 %rd58, %r7;
    cvt.s64.s32 %rd59, %r46;

    mul.lo.s64 %rd60, %rd55, %rd41;
    add.s64 %rd61, %rd60, %rd42;
    mul.lo.s64 %rd62, %rd61, %rd56;
    add.s64 %rd63, %rd62, %rd57;
    mul.lo.s64 %rd64, %rd63, %rd58;
    add.s64 %rd65, %rd64, %rd59;
    shl.b64 %rd66, %rd65, 2;
    add.s64 %rd67, %rd11, %rd66;
    ld.global.nc.f32 %f3, [%rd67];

    fma.rn.f32 %f1, %f2, %f3, %f1;

SKIP_KW:
    add.s32 %r46, %r46, 1;
    bra LOOP_KW;

END_KW:
SKIP_KH:
    add.s32 %r41, %r41, 1;
    bra LOOP_KH;

END_KH:
    add.s32 %r40, %r40, 1;
    bra LOOP_CI;

END_CI:
    // Y index = ((n*Cout + oc)*Hout + oh)*Wout + ow
    cvt.s64.s32 %rd70, %r34;
    cvt.s64.s32 %rd71, %r5;
    cvt.s64.s32 %rd72, %r35;
    cvt.s64.s32 %rd73, %r13;
    cvt.s64.s32 %rd74, %r33;
    cvt.s64.s32 %rd75, %r14;
    cvt.s64.s32 %rd76, %r31;

    mul.lo.s64 %rd77, %rd70, %rd71;
    add.s64 %rd78, %rd77, %rd72;
    mul.lo.s64 %rd79, %rd78, %rd73;
    add.s64 %rd80, %rd79, %rd74;
    mul.lo.s64 %rd81, %rd80, %rd75;
    add.s64 %rd82, %rd81, %rd76;
    shl.b64 %rd83, %rd82, 2;
    add.s64 %rd84, %rd12, %rd83;
    st.global.f32 [%rd84], %f1;

