_MODULE = None


def _get_module() -> PtxModule:
    global _MODULE
    if _MODULE is None:
        _MODULE = PtxModule(PTX_SOURCE)
    return _MODULE


def validate_generated_code():
    """Sanity-check that the PTX module contains the expected entry point."""
    module = _get_module()
    kernel = module.function("conv2d_kernel")
    assert kernel is not None, "conv2d_kernel entry not found in PTX module"
    return kernel


class ModelNew(nn.Module):
    """
    Standard 2D convolution with square input, asymmetric kernel, dilation and
    padding, implemented with a hand-written PTX kernel launched through
    cutegen.ptx_runtime.PtxModule.
    """

    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: tuple,
                 stride: int = 1,
                 padding: tuple = (0, 0),
                 dilation: tuple = (1, 1),
                 bias: bool = False) -> None:
        super().__init__()

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = tuple(kernel_size)
        self.stride = int(stride)
        self.padding = tuple(padding)
        self.dilation = tuple(dilation)

        Cin = self.in_channels
        Cout = self.out_channels
        Kh, Kw = self.kernel_size

        self.weight = nn.Parameter(torch.empty(Cout, Cin, Kh, Kw))
        if bias:
            self.bias = nn.Parameter(torch.empty(Cout))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()

        self._module = None
        self._kernel = None

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            Cin = self.in_channels
            Kh, Kw = self.kernel_size
            fan_in = Cin * Kh * Kw
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def _ensure_module(self):
        if self._module is None:
            self._module = _get_module()
            self._kernel = self._module.function("conv2d_kernel")
        return self._module, self._kernel

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "input must be a CUDA tensor"
        assert x.dtype == torch.float32, "input must be float32"

        module, kernel = self._ensure_module()

        x_c = x.contiguous()
        w_c = self.weight.contiguous()

        N, Cin, H, Win = x_c.shape
        Cout, Cin_w, Kh, Kw = w_c.shape
        assert Cin_w == Cin, "weight Cin mismatch"

        stride = self.stride
        pad_h, pad_w = self.padding
        dil_h, dil_w = self.dilation

        Hout = (H + 2 * pad_h - dil_h * (Kh - 1) - 1) // stride + 1
        Wout = (Win + 2 * pad_w - dil_w * (Kw - 1) - 1) // stride + 1
        assert Hout > 0 and Wout > 0, "invalid output size computed"

        y = torch.empty((N, Cout, Hout, Wout), device=x.device, dtype=torch.float32)

        if self.bias is not None:
            b_c = self.bias.contiguous()
            b_ptr = b_c.data_ptr()
        else:
            b_c = None
            b_ptr = 0

        total = N * Cout * Hout * Wout
        block_x = 256
        grid_x = (total + block_x - 1) // block_x

        stream = torch.cuda.current_stream(device=x.device).cuda_stream

        module.launch(
            kernel,
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            args=[
                u64(x_c.data_ptr()),
                u64(w_c.data_ptr()),
                u64(b_ptr),
                u64(y.data_ptr()),
                i32(N),
                i32(Cin),
                i32(H),
                i32(Win),
                i32(Cout),
                i32(Kh),
                i32(Kw),
                i32(stride),
                i32(pad_h),
                i32(pad_w),
                i32(dil_h),
                i32(dil_w),
                i32(Hout),
                i32(Wout),
            ],
            stream=stream,
        )

        return y
